/* Independent network calculations used by both the interface and tests. */
const Net = (() => {
 const ip = s => { if(typeof s!=='string'||!/^\d+\.\d+\.\d+\.\d+$/.test(s.trim()))throw Error('Enter four decimal octets separated by dots.'); const a=s.trim().split('.').map(Number); if(a.some(n=>n<0||n>255))throw Error('IPv4 octets must be between 0 and 255.'); return a.reduce((v,n)=>v*256+n,0); };
 const str = n => [24,16,8,0].map(b=>Math.floor(n/2**b)%256).join('.');
 const subnet=(s,p)=>{if(p===undefined){const a=s.split('/');if(a.length!==2)throw Error('Use CIDR notation, for example 192.168.10.0/26.');[s,p]=a;} if(!/^\/?\d+$/.test(String(p)))throw Error('Prefix must be an integer from 0 to 32.');p=Number(String(p).replace('/',''));if(p<0||p>32)throw Error('Prefix must be between 0 and 32.');const n=ip(s),size=2**(32-p),start=Math.floor(n/size)*size,end=start+size-1;return{ip:s,p,size,start,end,network:str(start),broadcast:p<31?str(end):'Not used',lastAddress:str(end),first:str(start+(p<31?1:0)),last:str(end-(p<31?1:0)),hosts:p<31?size-2:size,mask:str(2**32-size),wildcard:str(size-1),cidr:str(start)+'/'+p};};
 const binary=n=>str(n).split('.').map(x=>Number(x).toString(2).padStart(8,'0')).join('.');
 const classify=s=>{const n=ip(s),a=Number(s.split('.')[0]);let type='Unicast (check special-purpose registry for routing eligibility)';if(a===10||(n>=ip('172.16.0.0')&&n<=ip('172.31.255.255'))||(n>=ip('192.168.0.0')&&n<=ip('192.168.255.255')))type='Private (RFC 1918)';else if(a===127)type='Loopback';else if(n>=ip('169.254.0.0')&&n<=ip('169.254.255.255'))type='Link-local';else if(a===0)type='This network / unspecified';else if(a>=224&&a<=239)type='Multicast';else if(a>=240)type='Reserved / limited broadcast';else if([['192.0.2.0',24],['198.51.100.0',24],['203.0.113.0',24]].some(([s,p])=>{const b=subnet(s,p);return n>=b.start&&n<=b.end;}))type='Documentation (RFC 5737)';return{class:a<128?'A':a<192?'B':a<224?'C':a<240?'D':'E',type};};
 const list=s=>{const a=s.trim().split(/[\n,]+/).map(x=>x.trim()).filter(Boolean);if(!a.length)throw Error('Enter at least one CIDR block.');return a.map(x=>subnet(x));};
 const overlap=a=>a.flatMap((x,i)=>a.slice(i+1).filter(y=>x.start<=y.end&&y.start<=x.end).map(y=>[x.cidr,y.cidr,str(Math.max(x.start,y.start)),str(Math.min(x.end,y.end))]));
 const summarize=a=>{let lo=Math.min(...a.map(x=>x.start)),hi=Math.max(...a.map(x=>x.end)),p=32;while(Math.floor(lo/2**(32-p))!==Math.floor(hi/2**(32-p)))p--;return subnet(str(lo),p);};
 const merge=a=>{let ranges=a.map(x=>[x.start,x.end]).sort((a,b)=>a[0]-b[0]),r=[];for(const [s,e]of ranges){if(r.length&&s<=r.at(-1)[1]+1)r.at(-1)[1]=Math.max(e,r.at(-1)[1]);else r.push([s,e]);}let out=[];for(let [s,e]of r){while(s<=e){let bits=0;while(bits<32&&s%(2**(bits+1))===0&&s+2**(bits+1)-1<=e)bits++;out.push(subnet(str(s),32-bits));s+=2**bits;}}return out;};
 const vlsm=(base,req)=>{let cursor=base.start;const allocations=req.map((r,i)=>{if(!Number.isInteger(r.hosts)||r.hosts<1||r.hosts>2**32-2)throw Error('Host requirements must be positive integers.');return{...r,index:i,size:2**Math.ceil(Math.log2(r.hosts+2))};}).sort((a,b)=>b.size-a.size);return allocations.map(r=>{cursor=Math.ceil(cursor/r.size)*r.size;if(cursor+r.size-1>base.end)throw Error('The requirements do not fit inside the base network.');const b=subnet(str(cursor),32-Math.log2(r.size));cursor+=r.size;return{...r,...b,required:r.hosts};});};
 const expand6=s=>{s=s.trim().toLowerCase();if(s.includes('.')){const last=s.slice(s.lastIndexOf(':')+1),n=ip(last);s=s.slice(0,s.lastIndexOf(':')+1)+Math.floor(n/65536).toString(16)+':'+(n%65536).toString(16);}if(!/^[0-9a-f:]+$/.test(s)||s.split('::').length>2)throw Error('Enter a valid IPv6 address without a zone or prefix.');const halves=s.split('::'),left=halves[0]?halves[0].split(':'):[],right=halves.length>1&&halves[1]?halves[1].split(':'):[];let a;if(halves.length===2){if(left.length+right.length>=8)throw Error('The :: must replace at least one group.');a=[...left,...Array(8-left.length-right.length).fill('0'),...right];}else a=left;if(a.length!==8||a.some(x=>!/^[0-9a-f]{1,4}$/.test(x)))throw Error('IPv6 requires eight valid groups, or :: compression.');return a.map(x=>x.padStart(4,'0'));};
 const compress6=a=>{a=a.map(x=>parseInt(x,16).toString(16));let start=-1,len=1;for(let i=0;i<8;i++){if(a[i]!=='0')continue;let j=i;while(j<8&&a[j]==='0')j++;if(j-i>len){start=i;len=j-i;}i=j-1;}return start<0?a.join(':'):a.slice(0,start).join(':')+'::'+a.slice(start+len).join(':');};
 const int6=s=>BigInt('0x'+expand6(s).join(''));
 const str6=n=>compress6(n.toString(16).padStart(32,'0').match(/.{4}/g));
 const subnet6=s=>{const [addr,pText]=s.split('/'),p=Number(pText);if(pText===undefined||!/^\d+$/.test(pText)||p<0||p>128)throw Error('IPv6 prefix must be 0–128.');const n=int6(addr),size=1n<<BigInt(128-p),start=n/size*size;return{p,size,start,end:start+size-1n,cidr:str6(start)+'/'+p};};
 const mac=s=>{if(!/^[0-9a-fA-F: .-]+$/.test(s))throw Error('Use a 48-bit hexadecimal MAC address.');const h=s.replace(/[: .-]/g,'').toUpperCase();if(!/^[0-9A-F]{12}$/.test(h))throw Error('A MAC address must contain 12 hexadecimal digits.');return h.match(/../g);};
 const bestBGP=routes=>{const candidates=routes.filter(r=>r.reachable!==false);if(!candidates.length)throw Error('No route has a reachable next hop.');const rules=[['weight',-1],['localPref',-1],['local',-1],['pathLength',1],['origin',1],['med',1],['ibgp',1],['igp',1],['routerId',1]];let decisive='Equal attributes';let remaining=[...candidates];for(const [key,dir]of rules){if(remaining.length===1)break;const val=dir<0?Math.max(...remaining.map(r=>r[key]||0)):Math.min(...remaining.map(r=>r[key]||0));const next=remaining.filter(r=>(r[key]||0)===val);if(next.length<remaining.length)decisive=key;remaining=next;}return{winner:remaining[0],decisive};};
 const spf=(count,links,source=0)=>{const dist=Array(count).fill(Infinity),prev=Array(count).fill(null),seen=new Set();dist[source]=0;for(let k=0;k<count;k++){let u=-1;for(let i=0;i<count;i++)if(!seen.has(i)&&(u<0||dist[i]<dist[u]))u=i;if(u<0||dist[u]===Infinity)break;seen.add(u);for(const l of links){if(l.down)continue;const v=l.a===u?l.b:l.b===u?l.a:-1;if(v>=0&&dist[u]+l.cost<dist[v]){dist[v]=dist[u]+l.cost;prev[v]=u;}}}return{dist,prev};};
 const randomInt=max=>{const range=2**32,limit=Math.floor(range/max)*max,b=new Uint32Array(1);do{crypto.getRandomValues(b);}while(b[0]>=limit);return b[0]%max;};
 return{ip,str,subnet,binary,classify,list,overlap,summarize,merge,vlsm,expand6,compress6,int6,str6,subnet6,mac,bestBGP,spf,randomInt};
})();
if(typeof module!=='undefined')module.exports=Net;
